const body = $json.body || {};
const raw = body.execute_after || '';
const d = new Date(raw);
if (isNaN(d.getTime())) throw new Error('execute_after is not a valid datetime: ' + raw);
const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Athens', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
const p = Object.fromEntries(fmt.formatToParts(d).map(x => [x.type, x.value]));
// n8n Wait node needs YYYY-MM-DDTHH:mm:ss in workflow TZ (Europe/Athens), no ms/offset
const wait_until = `${p.year}-${p.month}-${p.day}T${p.hour === '24' ? '00' : p.hour}:${p.minute}:${p.second}`;
return [{ json: { wait_until } }];

const crypto = require('crypto');
const secret = ($env.SOCIAL_TOTP_SECRET || '').trim().replace(/\s+/g, '').toUpperCase();
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
const clean = secret.replace(/=+$/, '');
let bits = 0, value = 0;
const bytes = [];
for (const ch of clean) {
  const idx = ALPHABET.indexOf(ch);
  if (idx === -1) throw new Error('Invalid base32 char in SOCIAL_TOTP_SECRET');
  value = (value << 5) | idx;
  bits += 5;
  if (bits >= 8) { bytes.push((value >>> (bits - 8)) & 0xff); bits -= 8; }
}
const key = Buffer.from(bytes);
const msg = Buffer.alloc(8);
msg.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000)));
const digest = crypto.createHmac('sha1', key).update(msg).digest();
const offset = digest[digest.length - 1] & 0x0f;
const otp = ((digest.readUInt32BE(offset) & 0x7fffffff) % 1000000).toString().padStart(6, '0');
return [{ json: { otp } }];

const body = $('Deferred Reply Webhook').item.json.body || {};
const kw = (body.match_keywords || ['hikerapi', 'xpoz', 'instagrapi', 'throttle', 'proxies'])
  .map(k => String(k).toLowerCase());
const convos = ($json.conversations || []);
const scored = [];
for (const c of convos) {
  const hay = ((c.name || '') + ' ' + (c.preview || '')).toLowerCase();
  const hit = kw.some(k => hay.includes(k));
  const unread = String(c.unread || '').trim() !== '';
  if (c.thread_id && (hit || unread)) scored.push({ thread_id: c.thread_id, name: c.name, preview: c.preview, hit, unread });
}
// Preview-matches first, then unread; cap navigations at 5 threads.
scored.sort((a, b) => (b.hit - a.hit) || (b.unread - a.unread));
let out = scored.slice(0, 5);
if (out.length === 0) {
  // No signal — fall back to the 3 most recent conversations.
  out = convos.filter(c => c.thread_id).slice(0, 3)
    .map(c => ({ thread_id: c.thread_id, name: c.name, preview: c.preview, hit: false, unread: false }));
}
if (out.length === 0) throw new Error('No LinkedIn conversations returned by sidecar');
return out.map(c => ({ json: c }));

const body = $('Deferred Reply Webhook').item.json.body || {};
const kw = (body.match_keywords || ['hikerapi', 'xpoz', 'instagrapi', 'throttle', 'proxies'])
  .map(k => String(k).toLowerCase());
const matches = [];
for (const item of $input.all()) {
  const msgs = (item.json && item.json.messages) || [];
  const hit = msgs.some(m => kw.some(k => String(m.text || '').toLowerCase().includes(k)));
  if (hit && item.json.thread_id) {
    matches.push({ json: { thread_id: item.json.thread_id, messages_found: msgs.length } });
  }
}
if (matches.length !== 1) {
  throw new Error('Expected exactly 1 matching thread, found ' + matches.length + ' — refusing to send to an ambiguous thread');
}
return matches;

